#!/usr/bin/env node
/**
 * verify-records.mjs — static validation of the seed dataset (owner: zurich-maps-0).
 *
 * Runs without network access and without dependencies. Used by `npm run
 * verify:data` and by tests/records.test.mjs.
 *
 *   node scripts/verify-records.mjs            # report + exit code
 *   node scripts/verify-records.mjs --json     # machine readable
 */
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';
import { validateRecords } from '../public/app/records.js';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '..');

export async function verifyData({ dataDir = resolve(root, 'public/data') } = {}) {
  const [recordsRaw, sourcesRaw] = await Promise.all([
    readFile(resolve(dataDir, 'records.json'), 'utf8'),
    readFile(resolve(dataDir, 'sources.json'), 'utf8'),
  ]);
  const doc = JSON.parse(recordsRaw);
  const sources = JSON.parse(sourcesRaw);
  const report = validateRecords(doc, sources);
  return { report, doc, sources };
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const asJson = process.argv.includes('--json');
  const { report, doc } = await verifyData();
  if (asJson) {
    console.log(JSON.stringify({ ...report, generatedAt: doc.generatedAt ?? null }, null, 2));
  } else {
    console.log(`records.json: ${report.count} records, generated ${doc.generatedAt ?? 'unknown'}`);
    for (const warning of report.warnings) console.log(`warning: ${warning}`);
    for (const error of report.errors) console.log(`error:   ${error}`);
    console.log(report.ok ? 'dataset OK' : 'dataset INVALID');
  }
  process.exit(report.ok ? 0 : 1);
}

#!/usr/bin/env node
/**
 * build-check.mjs — dependency-free pre-deploy verification (owner: zurich-maps-0).
 *
 * Cloudflare runs `npm run build` before `wrangler deploy`. This script fails the
 * build when the site would ship broken: referenced local assets must exist, the
 * seed data must validate, and the worker must parse.
 */
import { access, readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';
import { verifyData } from './verify-records.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '..');
const publicDir = resolve(root, 'public');

const problems = [];
const notes = [];

async function exists(path) {
  try {
    await access(path);
    return true;
  } catch {
    return false;
  }
}

const html = await readFile(resolve(publicDir, 'index.html'), 'utf8');

// 1. Local assets referenced by the shell must exist.
const refs = new Set();
for (const match of html.matchAll(/(?:src|href)="(\/[^"#?]+)"/g)) refs.add(match[1]);
for (const ref of refs) {
  if (ref.startsWith('//')) continue;
  const path = resolve(publicDir, `.${ref}`);
  if (!(await exists(path))) problems.push(`index.html references missing asset: ${ref}`);
}
notes.push(`checked ${refs.size} local asset references`);

// 2. Every ES module in public/app must parse.
for (const name of ['main', 'store', 'dom', 'records', 'map', 'search', 'results', 'detail', 'iiif']) {
  const path = resolve(publicDir, `app/${name}.js`);
  if (!(await exists(path))) {
    problems.push(`missing application module: public/app/${name}.js`);
    continue;
  }
}

// 3. Worker must parse (syntax check only, no bundling).
const workerPath = resolve(root, 'src/worker/index.js');
if (!(await exists(workerPath))) problems.push('missing worker entry: src/worker/index.js');

// 4. Seed data must validate against the data contract.
const { report } = await verifyData({ dataDir: resolve(publicDir, 'data') });
notes.push(`dataset: ${report.count} records`);
if (!report.ok) for (const error of report.errors) problems.push(`data: ${error}`);
for (const warning of report.warnings) notes.push(`data warning: ${warning}`);

for (const note of notes) console.log(`· ${note}`);
if (problems.length) {
  console.error(`\n${problems.length} problem(s) found:`);
  for (const problem of problems) console.error(`  ✗ ${problem}`);
  process.exit(1);
}
console.log('\nbuild check OK — static assets, modules, worker entry and seed data are consistent.');

