test('normalizeRecord keeps upstream values and coerces the contract fields', () => {
  const record = normalizeRecord({ id: 7, title: '  T  ', yearStart: '1853', creators: null });
  assert.equal(record.id, '7');
  assert.equal(record.title, 'T');
  assert.equal(record.yearStart, 1853);
  assert.deepEqual(record.creators, []);
  assert.equal(record.geo, null);
  assert.equal(record.extent, null);
});

test('toRecordList accepts arrays and dataset objects and drops unusable rows', () => {
  assert.equal(toRecordList({ records: [{ id: 'a:1', title: 'x' }, { id: '', title: 'y' }] }).length, 1);
  assert.equal(toRecordList([]).length, 0);
});

test('dateRange prefers the depicted date but never invents one', () => {
  const depicted = normalizeRecord({ id: 'a:1', title: 't', yearStart: 1890, depictedYearStart: 1850, depictedYearEnd: 1855 });
  assert.deepEqual(dateRange(depicted), { start: 1850, end: 1855, basis: 'depicted' });
  assert.equal(formatYear(depicted), 'um 1850–1855');
  const published = normalizeRecord({ id: 'a:2', title: 't', yearStart: 1890, yearEnd: 1892 });
  assert.deepEqual(dateRange(published), { start: 1890, end: 1892, basis: 'publication' });
  assert.equal(formatYear(published), '1890–1892');
  assert.equal(formatYear(normalizeRecord({ id: 'a:3', title: 't' })), 'ohne Jahr');
});

test('recordOverlapsYears implements the time filter and keeps undated items', () => {
  assert.equal(recordOverlapsYears(fixture[0], 1850, 1860), true);
  assert.equal(recordOverlapsYears(fixture[0], 1700, 1800), false);
  assert.equal(recordOverlapsYears(fixture[0], null, null), true);
  const undated = normalizeRecord({ id: 'a:4', title: 't' });
  assert.equal(recordOverlapsYears(undated, 1800, 1850), true);
});

test('filterRecords combines text, years, provider and viewport', () => {
  const state = { text: '', from: 1700, to: 2000, provider: 'all' };
  assert.equal(filterRecords(state, fixture).length, 3);
  assert.equal(filterRecords({ ...state, text: 'brack' }, fixture).length, 1);
  assert.equal(filterRecords({ ...state, provider: 'swisstopo' }, fixture).length, 1);
  assert.equal(filterRecords({ ...state, provider: 'e-rara,swisstopo' }, fixture).length, 3);
  const zurich = { west: 8.5, east: 8.6, south: 47.3, north: 47.4 };
  const inView = filterRecords(state, fixture, { bounds: zurich, viewportOnly: true });
  assert.deepEqual(inView.map((r) => r.id), ['e-rara:1']);
  assert.equal(filterRecords(state, fixture, { bounds: zurich, viewportOnly: false }).length, 3);
});

test('bbox and point geometry tests behave correctly', () => {
  const zurich = { west: 8.5, east: 8.6, south: 47.3, north: 47.4 };
  assert.equal(recordInBounds(fixture[0], zurich), true);
  assert.equal(recordInBounds(fixture[1], zurich), false);
  assert.equal(recordInBounds(fixture[2], zurich), false);
  assert.equal(hasLocation(fixture[2]), false);
  assert.equal(recordsInBounds(fixture, zurich).length, 1);
});

test('searchRecords matches accented and multi-term queries', () => {
  assert.equal(searchRecords(fixture, 'zürich').length, 1);
  assert.equal(searchRecords(fixture, 'kanton zürich').length, 1);
  assert.equal(searchRecords(fixture, 'nichts').length, 0);
});

test('sortRecords orders by year descending by default and is stable', () => {
  assert.deepEqual(sortRecords(fixture).map((r) => r.id), ['swisstopo:zeitreihe-1900', 'e-rara:1', 'e-rara:2']);
  assert.deepEqual(sortRecords(fixture, 'year-asc').map((r) => r.id), ['e-rara:2', 'e-rara:1', 'swisstopo:zeitreihe-1900']);
});

test('buildIndex and yearDomain produce the slider domain', () => {
  const index = buildIndex(fixture);
  assert.equal(index.total, 3);
  assert.equal(index.providerCounts.get('e-rara'), 2);
  assert.equal(index.geolocated, 2);
  assert.deepEqual(yearDomain(index), { min: 1780, max: 1900 });
  assert.equal(institutionShort(fixture[0]), 'ZB Zürich');
});

test('loadDataset reads and normalises a dataset document', async () => {
  const doc = { records: [{ id: 'e-rara:1', title: 'T', yearStart: 1853 }], generatedAt: 'x' };
  const dataset = await loadDataset({
    url: 'memory://records',
    fetchImpl: async (url) => {
      assert.equal(url, 'memory://records');
      return { ok: true, json: async () => doc };
    },
  });
  assert.equal(dataset.records.length, 1);
  assert.equal(dataset.records[0].id, 'e-rara:1');
  await assert.rejects(() => loadDataset({ fetchImpl: async () => ({ ok: false, status: 500 }) }));
});

test('shipped records.json satisfies the data contract', async () => {
  const [doc, sources] = await Promise.all([readJson('records.json'), readJson('sources.json')]);
  const report = validateRecords(doc, sources);
  assert.deepEqual(report.errors, []);
  assert.ok(report.count >= 20, `expected a usable seed set, got ${report.count}`);
  for (const record of doc.records) {
    assert.match(record.recordUrl, /^https:\/\//);
    assert.ok(record.institution, `${record.id} needs an institution`);
    assert.ok(record.rights, `${record.id} needs a rights statement`);
  }
});

test('every e-rara record points at a resolvable IIIF manifest pattern', async () => {
  const doc = await readJson('records.json');
  for (const record of doc.records) {
    if (record.providerId !== 'e-rara') continue;
    assert.match(record.iiifManifest ?? '', /^https:\/\/www\.e-rara\.ch\/i3f\/v\d+\/\d+\/manifest$/);
    assert.match(record.thumbnail ?? '', /^https:\/\/www\.e-rara\.ch\/i3f\/v\d+\/\d+\//);
  }
});

test('swisstopo overlays use the documented WMTS template and attribution', async () => {
  const overlays = await readJson('overlays.json');
  assert.ok(overlays.overlays.length > 0);
  for (const overlay of overlays.overlays) {
    assert.match(overlay.urlTemplate, /^https:\/\/wmts\.geo\.admin\.ch\/1\.0\.0\/[\w.-]+\/default\/\{Time\}\/3857\//);
    assert.ok(overlay.attribution.includes('swisstopo'), `${overlay.id} needs swisstopo attribution`);
  }
  const zeitreihen = overlays.overlays.find((o) => o.id === 'ch.swisstopo.zeitreihen');
  assert.ok(zeitreihen, 'Zeitreise layer must be part of the curated overlay set');
  assert.ok(zeitreihen.timeValues.length > 100, 'Zeitreise editions come from the WMTS Time dimension');
});

test('source registry documents endpoints, rights and retrieval date', async () => {
  const sources = await readJson('sources.json');
  const ids = sources.providers.map((provider) => provider.id);
  assert.ok(ids.includes('e-rara'));
  assert.ok(ids.includes('swisstopo'));
  for (const provider of sources.providers) {
    assert.ok(provider.retrievalDate, `${provider.id} must record a retrieval date`);
    assert.ok(provider.rights, `${provider.id} must record rights`);
    assert.ok(provider.attribution, `${provider.id} must record attribution`);
  }
});

