/**
 * tests/records.test.mjs — data layer + shipped-dataset tests.
 * Owner: zurich-maps-0. `node --test`, no dependencies, no network.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

import {
  bboxIntersects,
  extentUnion,
  facets,
  filterRecords,
  indexRecords,
  loadRecords,
  loadSources,
  matchesQuery,
  overlapsRange,
  recordCenter,
  recordsInBounds,
  sortRecords,
  validateRecord,
  yearBounds,
} from '../public/app/records.js';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const readJson = async (name) => JSON.parse(await readFile(resolve(root, 'public/data', name), 'utf8'));

const record = (overrides = {}) => ({
  id: 'e-rara:27955',
  title: 'Karte des Kantons Zürich im Masstab von 1:25 000',
  yearStart: 1866,
  yearEnd: 1866,
  creators: ['Brack, Johann Jakob'],
  providerId: 'e-rara',
  institution: 'Zentralbibliothek Zürich',
  rights: 'PDM 1.0',
  recordUrl: 'https://www.e-rara.ch/doi/10.3931/e-rara-27955',
  thumbnail: 'https://www.e-rara.ch/i3f/v20/8924033/full/304/0/default.jpg',
  iiifManifest: 'https://www.e-rara.ch/i3f/v20/8924032/manifest',
  type: 'map',
  extent: { west: 8.4, east: 8.9, south: 47.2, north: 47.5 },
  ...overrides,
});

test('validateRecord accepts a contract-conforming record and reports every missing field', () => {
  assert.deepEqual(validateRecord(record()), []);
  const problems = validateRecord({ id: 'x', yearStart: 1900, yearEnd: 1899, recordUrl: 'http://x' });
  assert.ok(problems.some((p) => p.includes('missing title')));
  assert.ok(problems.some((p) => p.includes('id must be')));
  assert.ok(problems.some((p) => p.includes('recordUrl must be https')));
  assert.ok(problems.some((p) => p.includes('yearStart > yearEnd')));
  assert.deepEqual(validateRecord(null), ['record[-1] is not an object']);
});

test('validateRecord rejects inverted bboxes and non-https overlay templates', () => {
  const problems = validateRecord(
    record({ extent: { west: 9, east: 8, south: 47.5, north: 47.2 } , overlay: { urlTemplate: 'http://tiles.example/{z}' } }),
  );
  assert.ok(problems.some((p) => p.includes('extent bounds inverted')));
  assert.ok(problems.some((p) => p.includes('overlay.urlTemplate must be https')));
});

test('matchesQuery searches title, creators and institution', () => {
  assert.equal(matchesQuery(record(), ''), true);
  assert.equal(matchesQuery(record(), 'kanton brack'), true);
  assert.equal(matchesQuery(record(), 'zentralbibliothek'), true);
  assert.equal(matchesQuery(record(), 'rheinau'), false);
});

test('overlapsRange implements the time filter and keeps undated records', () => {
  assert.equal(overlapsRange(record(), 1860, 1870), true);
  assert.equal(overlapsRange(record(), 1700, 1800), false);
  assert.equal(overlapsRange({ yearStart: undefined, yearEnd: undefined }, 1700, 1800), true);
});

test('filterRecords combines text, years, provider and type', () => {
  const records = [
    record(),
    record({ id: 'e-rara:2', title: 'Rheinau', yearStart: 1780, yearEnd: 1780, type: 'atlas' }),
    record({ id: 'swisstopo:1', title: 'Zeitreise', providerId: 'swisstopo', yearStart: 1950, yearEnd: 1950, extent: undefined, geo: { lat: 46.8, lon: 8.2 } }),
  ];
  const state = { q: '', from: 1700, to: 2000, provider: '', type: '' };
  assert.equal(filterRecords(state, records).length, 3);
  assert.equal(filterRecords({ ...state, q: 'rheinau' }, records).length, 1);
  assert.equal(filterRecords({ ...state, provider: 'e-rara' }, records).length, 2);
  assert.equal(filterRecords({ ...state, type: 'atlas' }, records).length, 1);
  assert.equal(filterRecords({ ...state, from: 1800, to: 2000 }, records).length, 2);
});

test('sortRecords orders by year ascending, descending and title', () => {
  const records = [record({ id: 'a:1', yearStart: 1866 }), record({ id: 'a:2', yearStart: 1780 }), record({ id: 'a:3', yearStart: 1950 })];
  assert.deepEqual(sortRecords(records).map((r) => r.id), ['a:2', 'a:1', 'a:3']);
  assert.deepEqual(sortRecords(records, 'year-desc').map((r) => r.id), ['a:3', 'a:1', 'a:2']);
  assert.equal(sortRecords(records, 'title').length, 3);
  assert.deepEqual(records.map((r) => r.id), ['a:1', 'a:2', 'a:3'], 'sortRecords must not mutate its input');
});

test('geometry helpers treat extents and points consistently', () => {
  const view = { west: 8.5, east: 8.6, south: 47.3, north: 47.4 };
  const records = [record(), record({ id: 'swisstopo:1', extent: undefined, geo: { lat: 46.8, lon: 8.2 } }), record({ id: 'e-rara:3', extent: undefined })];
  assert.equal(bboxIntersects(record().extent, view), true);
  assert.equal(recordsInBounds(records, view).length, 1);
  assert.equal(recordsInBounds(records, null).length, 3);
  assert.deepEqual(recordCenter(records[1]), { lat: 46.8, lon: 8.2 });
  assert.deepEqual(recordCenter(records[2]), null);
  assert.deepEqual(extentUnion(records), { west: 8.4, east: 8.9, south: 47.2, north: 47.5 });
});

test('index, facets and year bounds describe the collection', () => {
  const records = [record(), record({ id: 'e-rara:2', yearStart: 1780, yearEnd: 1785, type: 'atlas' })];
  const index = indexRecords(records);
  assert.equal(index.get('e-rara:2').yearStart, 1780);
  assert.deepEqual(yearBounds(records), { min: 1780, max: 1866 });
  const { providers, types } = facets(records);
  assert.equal(providers.get('e-rara'), 2);
  assert.equal(types.get('atlas'), 1);
  assert.deepEqual(yearBounds([]), { min: 1500, max: new Date().getFullYear() });
});

test('loadRecords validates fetched data and fails loudly on HTTP errors', async () => {
  const ok = await loadRecords(async () => ({
    ok: true,
    json: async () => ({ records: [record()], generatedAt: '2026-10-18T00:00:00Z' }),
  }));
  assert.equal(ok.ok, true);
  assert.equal(ok.records.length, 1);
  assert.equal(ok.generatedAt, '2026-10-18T00:00:00Z');

  const broken = await loadRecords(async () => ({ ok: true, json: async () => ({ records: [{ id: 'nope' }] }) }));
  assert.equal(broken.ok, false);
  assert.ok(broken.errors.length > 0);

  await assert.rejects(() => loadRecords(async () => ({ ok: false, status: 503 })), /503/);
  assert.deepEqual(await loadRecords(null), { records: [], errors: ['no fetch implementation'], ok: false });
});

test('shipped records.json satisfies the data contract and names its sources', async () => {
  const [doc, sources] = await Promise.all([readJson('records.json'), readJson('sources.json')]);
  const providerIds = new Set(sources.providers.map((p) => p.id));
  const ids = new Set();
  assert.ok(doc.records.length >= 20, `expected a usable seed collection, found ${doc.records.length}`);
  assert.ok(doc.generatedAt, 'records.json must record when it was generated');
  assert.ok(doc.method, 'records.json must document how it was built');
  for (const entry of doc.records) {
    assert.deepEqual(validateRecord(entry), [], `${entry.id} violates the record contract`);
    assert.ok(!ids.has(entry.id), `duplicate id ${entry.id}`);
    ids.add(entry.id);
    assert.ok(providerIds.has(entry.providerId), `${entry.id}: providerId must be in sources.json`);
    assert.match(entry.recordUrl, /^https:\/\//);
    assert.ok(entry.institution && entry.rights && entry.thumbnail);
  }
});

test('e-rara records point at real IIIF manifests and image services', async () => {
  const doc = await readJson('records.json');
  const erara = doc.records.filter((entry) => entry.providerId === 'e-rara');
  assert.ok(erara.length > 0);
  for (const entry of erara) {
    assert.match(entry.iiifManifest, /^https:\/\/www\.e-rara\.ch\/i3f\/v\d+\/\d+\/manifest$/);
    assert.match(entry.thumbnail, /^https:\/\/www\.e-rara\.ch\/i3f\/v\d+\/\d+\//);
    assert.match(entry.recordUrl, /^https:\/\/www\.e-rara\.ch\/(zuz\/)?(doi|content)\//);
  }
});

test('publication and depicted dates stay separate', async () => {
  const doc = await readJson('records.json');
  for (const entry of doc.records) {
    const depicted = [entry.depictedYearStart, entry.depictedYearEnd].filter((v) => v !== null && v !== undefined);
    if (depicted.length === 0) continue;
    for (const year of depicted) {
      assert.ok(Number.isInteger(year), `${entry.id}: depicted years must be integers`);
      assert.ok(year >= 1400 && year <= 2100, `${entry.id}: implausible depicted year ${year}`);
    }
  }
});

test('swisstopo overlays use documented WMTS templates with attribution', async () => {
  const overlays = await readJson('overlays.json');
  assert.ok(overlays.overlays.length > 0);
  const ids = new Set();
  for (const overlay of overlays.overlays) {
    assert.match(overlay.urlTemplate, /^https:\/\/wmts\.geo\.admin\.ch\/1\.0\.0\/[\w.-]+\/default\/\{Time\}\/3857\//);
    assert.ok(overlay.attribution.includes('swisstopo'), `${overlay.id} needs swisstopo attribution`);
    assert.ok(Array.isArray(overlay.timeValues) && overlay.timeValues.length > 0, `${overlay.id} needs Time values`);
    assert.ok(!ids.has(overlay.id), `duplicate overlay ${overlay.id}`);
    ids.add(overlay.id);
  }
  const zeitreihen = overlays.overlays.find((o) => o.id === 'ch.swisstopo.zeitreihen');
  assert.ok(zeitreihen, 'the Zeitreise layer is the historical overlay this app is built around');
  assert.ok(zeitreihen.timeValues.length > 100, 'Zeitreise editions come from the WMTS Time dimension');
  for (const value of zeitreihen.timeValues) assert.match(value, /^\d{8}$/);
});

test('source registry documents endpoints, rights, attribution and retrieval date', async () => {
  const sources = await readJson('sources.json');
  const ids = sources.providers.map((p) => p.id);
  assert.ok(ids.includes('e-rara'));
  assert.ok(ids.includes('swisstopo'));
  for (const provider of sources.providers) {
    assert.ok(provider.retrievalDate, `${provider.id} must record a retrieval date`);
    assert.ok(provider.rights, `${provider.id} must record its rights statement`);
