test('loadSources returns the provider list', async () => {
  const sources = await loadSources(async () => ({ ok: true, json: async () => ({ providers: [{ id: 'e-rara' }] }) }));
  assert.deepEqual(sources.providers.map((p) => p.id), ['e-rara']);
