});

/**
 * tests/worker.test.mjs — request handler tests for the Cloudflare Worker.
 * Owner: zurich-maps-0 (tests), handler by zurich-maps-1.
 *
 * Runs the real handler with a mocked assets binding, `caches.default` and
 * `fetch`, so no network access is required.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

import worker, { ALLOWLIST, HTML_ESCAPE, VERSION, isAllowed } from '../src/worker/index.js';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const readText = (name) => readFile(resolve(root, 'public/data', name), 'utf8');

/** Minimal Workers runtime doubles. */
function runtime({ origin = 'https://kartenzeit.example' } = {}) {
  const calls = { asset: [], fetch: [], cachePut: 0 };
  const assets = {
    async fetch(request) {
      const url = new URL(request.url);
      calls.asset.push(url.pathname);
      if (url.pathname === '/data/records.json' || url.pathname === '/data/sources.json' || url.pathname === '/data/overlays.json') {
        const name = url.pathname.replace('/data/', '');
        return new Response(await readText(name), { headers: { 'content-type': 'application/json' } });
      }
      if (url.pathname === '/' || url.pathname === '/index.html') {
        return new Response('<!doctype html><title>Kartenzeit</title>', { headers: { 'content-type': 'text/html' } });
      }
      return new Response('not found', { status: 404 });
    },
  };
  const ctx = { waitUntil: () => {} };
  return {
    calls,
    env: { ASSETS: assets },
    ctx,
    get(path, init = {}) {
      return new Request(`${origin}${path}`, init);
    },
  };
}

function mockCaches() {
  const store = new Map();
  globalThis.caches = {
    default: {
      async match(request) {
        const hit = store.get(request.url);
        return hit ? hit.clone() : undefined;
      },
      async put(request, response) {
        store.set(request.url, response.clone());
      },
    },
  };
  return store;
}

test('the allowlist only permits https hosts with documented path prefixes', () => {
  assert.ok(ALLOWLIST.length > 0);
  for (const rule of ALLOWLIST) {
    assert.match(rule.host, /^[a-z0-9.-]+$/);
    assert.ok(rule.prefixes.length > 0, `${rule.host} needs at least one allowed path prefix`);
  }
  assert.equal(isAllowed(new URL('https://www.e-rara.ch/i3f/v20/22142031/manifest')), true);
  assert.equal(isAllowed(new URL('https://api3.geo.admin.ch/rest/services/api/SearchServer?type=locations')), true);
  assert.equal(isAllowed(new URL('http://www.e-rara.ch/i3f/v20/22142031/manifest')), false, 'plain http must be rejected');
  assert.equal(isAllowed(new URL('https://evil.example/i3f/manifest')), false, 'unknown hosts must be rejected');
  assert.equal(isAllowed(new URL('https://www.e-rara.ch/private/secret')), false, 'unlisted paths must be rejected');
});

test('GET /api/health reports the runtime and the upstreams in use', async () => {
  const { env, ctx, get } = runtime();
  const res = await worker.fetch(get('/api/health'), env, ctx);
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.ok, true);
  assert.equal(body.version, VERSION);
  assert.equal(body.runtime, 'cloudflare-workers');
  assert.deepEqual(body.upstreams.sort(), ALLOWLIST.map((r) => r.host).sort());
});

test('/api/records and /api/sources are served from the static assets with caching', async () => {
  const { env, ctx, get, calls } = runtime();
  const res = await worker.fetch(get('/api/records'), env, ctx);
  assert.equal(res.status, 200);
  assert.match(res.headers.get('cache-control'), /max-age=300/);
  const body = await res.json();
  assert.ok(Array.isArray(body.records) && body.records.length > 0);
  assert.deepEqual(calls.asset, ['/data/records.json']);

  const sources = await worker.fetch(get('/api/sources'), env, ctx);
  assert.equal(sources.status, 200);
  assert.ok((await sources.json()).providers.length > 0);
});

test('unknown API paths return JSON 404 and other methods return 405', async () => {
  const { env, ctx, get } = runtime();
  const missing = await worker.fetch(get('/api/nope'), env, ctx);
  assert.equal(missing.status, 404);
  assert.equal((await missing.json()).error, 'not_found');

  const post = await worker.fetch(get('/api/records', { method: 'POST' }), env, ctx);
  assert.equal(post.status, 405);
  assert.equal(post.headers.get('allow'), 'GET, HEAD');
});

test('non-API requests fall through to the static assets', async () => {
  const { env, ctx, get, calls } = runtime();
  const res = await worker.fetch(get('/'), env, ctx);
  assert.equal(res.status, 200);
  assert.match(await res.text(), /Kartenzeit/);
  assert.deepEqual(calls.asset, ['/']);
});

test('/api/search/places validates the query before touching upstream', async () => {
  const { env, ctx, get, calls } = runtime();
  mockCaches();
  globalThis.fetch = async () => {
    calls.fetch.push('called');
    return new Response(JSON.stringify({ results: [] }), { headers: { 'content-type': 'application/json' } });
  };
  const short = await worker.fetch(get('/api/search/places?q=R'), env, ctx);
  assert.equal(short.status, 400);
  const long = await worker.fetch(get(`/api/search/places?q=${'x'.repeat(400)}`), env, ctx);
  assert.equal(long.status, 400);
  assert.equal(calls.fetch.length, 0, 'invalid queries must not reach swisstopo');
});

test('/api/search/places proxies swisstopo and normalises the results', async () => {
  const { env, ctx, get } = runtime();
  mockCaches();
  let requested = null;
  globalThis.fetch = async (url) => {
    requested = String(url);
    return new Response(
      JSON.stringify({
        results: [
          {
            attrs: {
              label: '<b>Zürich (ZH)</b>',
              origin: 'gg25',
              lat: 47.37721252441406,
              lon: 8.527311325073242,
              geom_st_box2d: 'BOX(8.44688 47.319035,8.627198 47.435142)',
