import test from 'node:test';
import assert from 'node:assert/strict';
import { access, readFile } from 'node:fs/promises';
import { execFile } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';
import { promisify } from 'node:util';

import { parseJsonc } from '../scripts/validate.mjs';

const run = promisify(execFile);
const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const abs = (...parts) => resolve(root, ...parts);
const readText = (path) => readFile(abs(path), 'utf8');

test('index.html only references assets that ship in ./public', async () => {
  const html = await readText('public/index.html');
  const refs = new Set();
  for (const match of html.matchAll(/(?:src|href)="(\/[^"#?]+)"/g)) refs.add(match[1]);
  assert.ok(refs.size >= 5, `expected the shell to reference its styles, fonts and modules, found ${refs.size}`);
  for (const ref of refs) {
    await access(abs('public', `.${ref}`)).catch(() => assert.fail(`missing asset referenced by index.html: ${ref}`));
  }
});

test('the application modules are dependency-free ES modules that parse', async () => {
  const modules = ['main', 'store', 'dom', 'records', 'map', 'search', 'results', 'detail'];
  for (const name of modules) {
    const path = `public/app/${name}.js`;
    await access(abs(path)).catch(() => assert.fail(`missing module ${path}`));
    // `node --check` on an ES module: throws on syntax errors.
    await run(process.execPath, ['--check', path]);
    const source = await readText(path);
    assert.equal(/from\s+['"]https?:/.test(source), false, `${path} must not import remote code`);
  }
});

test('the shell declares accessibility scaffolding for the map and the dialog', async () => {
  const html = await readText('public/index.html');
  assert.match(html, /<html lang="de-CH">/);
  assert.match(html, /class="[^"]*skip-link/, 'a skip link is required by eCH-0059/accessibility guidance');
  assert.match(html, /id="map"[^>]*(role="application"|tabindex="0")/, 'the map needs a keyboard entry point');
  assert.match(html, /<dialog/, 'the detail view is a native dialog');
  assert.match(html, /aria-live|role="status"/, 'status announcements keep screen-reader users informed');
  assert.match(html, /Designsystem Kanton Zürich|Kanton Zürich/, 'the canton design reference must be credited');
});

test('wrangler.jsonc wires the Workers static assets and the API handler', async () => {
  const config = parseJsonc(await readText('wrangler.jsonc'));
  assert.equal(config.assets.directory, './public');
  assert.equal(config.assets.binding, 'ASSETS');
  assert.ok(config.main && (await access(abs(config.main)).then(() => true)), 'main must exist');
  assert.deepEqual(config.assets.run_worker_first, ['/api/*'], 'only /api/* needs the Worker');
  assert.match(config.compatibility_date, /^\d{4}-\d{2}-\d{2}$/);
  assert.equal(config.assets.not_found_handling, 'single-page-application');
  assert.equal(JSON.stringify(config).includes('api_token'), false, 'no credentials may be committed');
