  assert.match(pkg.scripts['dry-run'], /wrangler deploy --dry-run/);
  assert.ok(pkg.devDependencies.wrangler, 'wrangler must be pinned as a dev dependency');
  assert.ok(pkg.engines?.node, 'the Node version used by the Cloudflare build must be declared');
});

